from admissions_records import *
def s(url,en,ru):return S(url,L(en,ru),access='web-html-read')
def save(id,routes,change,gaps=None):record(id,routes,change,gaps or ['Fall 2027-labelled applicability, exact IELTS variant/sections where unstated and individual qualification/waiver approval remain unconfirmed.'])

u='https://www.indwes.edu/pathways/international/international-campus'
save('indiana-wesleyan-university',[route(label=L('Marion campus international first-year admission','Международный приём первокурсников кампуса Marion'),english={'requirement':'required-unless-exempt','ielts':{'accepted':True,'min':6.5,'role':'admission'},'toefl':{'accepted':True,'scales':[{'period':'legacy','min':79}]},'alternatives':L('For students whose first language is not English: Duolingo 110 overall AND Production 110 is an alternative. The Bridge Program combines language and academic credits and is a separate support route.','Для кандидатов, у которых английский не родной: альтернатива Duolingo 110 overall И Production 110. Bridge Program сочетает язык и академические кредиты и является отдельным поддерживающим маршрутом.')},academic={'satPolicy':'conditional','note':L('General admission no longer incorporates standardised scores, but departments and the Foundations Review Committee may require SAT/ACT; named scholar programmes and placement have separate uses.','Общий приём больше не использует стандартизированные баллы, но факультеты и Foundations Review Committee могут требовать SAT/ACT; у названных scholar-программ и распределения отдельное использование.')},documents=[L('Official English transcripts and NACES-approved evaluation of non-US school records; do not substitute transfer-only evaluation instructions.','Официальные английские оценки и одобренная NACES оценка школьных документов вне США; не подменять это инструкциями только для перевода.')],sources=[s(u,'IWU Marion international language and testing conditions','IWU Marion: международные языковые и экзаменационные условия')])],'Preserved DET Production 110, Marion campus scope and conditional academic-testing exceptions.')

u='https://www.wcu.edu/learn/office-of-global-engagement/international-students/index.aspx'
save('western-carolina-university',[route(english={'requirement':'required-unless-exempt','ielts':{'accepted':True,'min':6,'sections':dict.fromkeys(['reading','writing','listening','speaking'],5),'role':'admission'},'toefl':{'accepted':True,'scales':[{'period':'legacy','min':75}]},'alternatives':L('Duolingo 95 or PTE Academic 50. The graduate table’s IELTS 6.5/6.0 is not the undergraduate requirement.','Duolingo 95 либо PTE Academic 50. IELTS 6,5/6,0 магистерской таблицы не является бакалаврским требованием.'),'waiver':L('Listed English-primary-country category, IB Diploma, completed English-medium school/higher education with an institutional letter, or 24+ US college credits may qualify.','Могут подойти указанная категория стран с основным английским, IB Diploma, завершённое англоязычное школьное/высшее образование с письмом учреждения либо 24+ кредита колледжа США.')},academic={'satPolicy':'conditional','note':L('The undergraduate international page requires SAT 880 or ACT 18 for applicants graduating from a US high school in their senior year. This school-history rule is not assigned to every foreign qualification.','Международная бакалаврская страница требует SAT 880 либо ACT 18 у выпускников школы США в последнем школьном году. Это правило истории школы не назначается каждой иностранной квалификации.')},sources=[s(u,'Western Carolina undergraduate versus graduate requirements','Western Carolina: бакалаврские и магистерские требования')])],'Scoped IELTS 6.0/5.0 and SAT school-history rule; excluded the graduate 6.5 table.')

u='https://css.loyno.edu/admissions/how-apply/international-undergraduate-students'
ss=[s(u,'Loyola New Orleans international degree, Pilot and LIEP routes','Loyola New Orleans: международные маршруты степени, Pilot и LIEP')]
aa={'satPolicy':'optional','note':L('SAT/ACT optional for admission; an accepted subscore may serve as English proof. Music/Media programmes have audition or interview conditions.','SAT/ACT необязательны для поступления; подходящая секция может подтвердить английский. У Music/Media условия прослушивания либо интервью.')}
save('loyola-university-new-orleans',[route(id='full-degree',english={'requirement':'required-unless-exempt','ielts':{'accepted':True,'min':6.5,'role':'admission'},'toefl':{'accepted':True,'scales':[{'period':'legacy','min':79}]},'alternatives':L('Duolingo 115; the table also lists CEFR C1/C2.','Duolingo 115; таблица также указывает CEFR C1/C2.'),'waiver':L('SAT Reading/Writing 560 or an A in AP/IB English is the published waiver wording. A generic ACT composite is not a verified English waiver.','Опубликованное освобождение: SAT Reading/Writing 560 либо A по AP/IB English. Обычный общий ACT не является проверенным языковым освобождением.')},academic=aa,sources=ss),route(id='pilot',kind='degree-with-esl',label=L('Pilot Program: degree credits plus intensive English','Pilot Program: кредиты степени и интенсивный английский'),english={'requirement':'required-unless-exempt','ielts':{'accepted':True,'min':5.5,'role':'admission'},'note':L('Published IELTS eligibility band 5.5–6.0; TOEFL 61–78 or DET 100–114. Conditional hybrid language/degree study, not full degree-seeking language readiness. LIEP below 5.5 is another preparatory route.','Опубликованный диапазон IELTS 5,5–6,0; TOEFL 61–78 либо DET 100–114. Условное совмещение языка/степени, а не полная языковая готовность degree-seeking. LIEP ниже 5,5 — другой подготовительный маршрут.')},academic=aa,sources=ss)],'Separated 6.5 full degree entry from the 5.5 Pilot support route and optional SAT language substitutes.')

u='https://www.lemoyne.edu/admission-financial-aid/apply/'
save('le-moyne-college',[route(english={'ielts':{'accepted':None},'note':L('The international page places IELTS 6.5, TOEFL 79 and DET 110 under Steps for Graduate Admission. Those numbers are not imported into first-year requirements without a separate undergraduate source.','Международная страница помещает IELTS 6,5, TOEFL 79 и DET 110 под Steps for Graduate Admission. Эти числа не переносятся в требования первокурсника без отдельного бакалаврского источника.')},academic={'satPolicy':'optional','note':L('The first-year checklist explicitly makes SAT/ACT optional and considers submitted scores only if they benefit the applicant. This does not establish a language-test exemption.','Список первокурсника прямо делает SAT/ACT необязательными и учитывает поданные баллы, только если они помогают кандидату. Это не устанавливает освобождение от языкового экзамена.')},documents=[L('Completed application, personal essay at least 250 words, one academic recommendation and official school transcript.','Заполненная заявка, личное эссе минимум 250 слов, одна академическая рекомендация и официальные школьные оценки.')],sources=[s(u,'Le Moyne first-year application requirements','Le Moyne: требования заявки первокурсника'),s('https://www.lemoyne.edu/admission-financial-aid/international-admission/','Le Moyne international page: separate undergraduate/graduate sections','Le Moyne: международная страница с отдельными разделами бакалавриата/магистратуры')])],'Established first-year optional SAT/ACT while preventing graduate English minima from becoming bachelor requirements.', ['Undergraduate English test acceptance/minima, sections, waivers and the Fall 2027 cycle remain unconfirmed.'])

u='https://uwf.edu/admissions/undergraduate/apply/international/requirements/'
save('university-of-west-florida',[route(id='freshman-0-11-credits',label=L('International freshman with 0–11 college credits','Иностранный первокурсник с 0–11 кредитами колледжа'),english={'ielts':{'accepted':None},'note':L('For fewer than 60 college credits, the page says English proof is met through the ACT/SAT admission requirements in Regulation 3.042. Its IELTS 6.0/TOEFL 79 or 4.5 table is specifically an alternative for 60+ credit transfers and is not assigned as a first-year route. Listed country exemptions still need individual assessment.','Для менее 60 кредитов страница связывает английский с требованиями ACT/SAT Regulation 3.042. Таблица IELTS 6,0/TOEFL 79 либо 4,5 является альтернативой для перевода с 60+ кредитами и не назначается первокурснику. Названные освобождения стран требуют индивидуальной оценки.')},academic={'satPolicy':'required-alternatives','note':L('Freshman applicants submit SAT, ACT or CLT and must meet the admission regulations. College-course substitution belongs to the separately specified transfer categories. The exact regulatory subscore thresholds still require verification.','Первокурсники подают SAT, ACT либо CLT и должны соответствовать правилам приёма. Замена предметами колледжа относится к отдельно указанным категориям перевода. Точные регуляторные пороги секций ещё требуют проверки.')},sources=[s(u,'UWF international first-year versus transfer requirement matrix','UWF: матрица международных требований первокурсника и перевода')])],'Stopped treating the 60+ credit transfer language-test table as the freshman English rule.', ['Full Regulation 3.042 section minima, country exceptions and Fall 2027-specific applicability remain unconfirmed.'])
finish()
